    waveFlatten();
    gl.uniform2fv(uD['uWvD[0]'], wvD);
    gl.uniform1fv(uD['uWvP[0]'], wvP);
    gl.uniform1fv(uD['uWvA[0]'], wvA);
    gl.uniform1f(uD.uWvLegacy, waveLegacy ? 1 : 0);
